// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address fuzzedCaller) public {
        // The admin is msg.sender of C's constructor, which is this test contract's setUp.
        // Only calls by the admin should succeed in changing the owner.
        // The fuzzer will supply a non-admin address, which should fail on the reference
        // but succeed on the mutant.
        vm.assume(fuzzedCaller != address(this));

        // Read the original owner set in the constructor (which is this test contract).
        address originalOwner = c.owner();
        address newOwner = address(0x1234); // arbitrary, not fuzzed but harmless; fuzzer controls caller

        bool success;
        vm.prank(fuzzedCaller);
        try c.setOwner(newOwner) returns (bool ret) {
            success = true;
        } catch {
            success = false;
        }

        // The reference onlyAdmin modifier should cause revert for any caller != admin,
        // so owner should remain unchanged. The buggy version has no modifier, so setOwner
        // succeeds and owner changes. The assertion captures this difference.
        assertTrue(!success || c.owner() == originalOwner);
    }
}

